// gamma.js — added by the edit script.
export function gammaJoin(parts) {
  return parts.join('-');
}

export function gammaFirst(items) {
  return items[0];
}

// beta.js — base fixture file. Independent of util.js; edited (1 chunk)
// and later deleted by the edit script.
export function betaScale(value, factor) {
  return value * factor * 2;
}

export function betaSum(a, b) {
  return a + b;
}

// util.js — base fixture file. A dependency target: other files import from it.
export function trimAllStrict(input) {
  return String(input).trim();
}

export function repeat(value, times) {
  let out = '';
  for (let i = 0; i < times; i += 1) out += value;
  return out;
}

// alpha.js — now imports the renamed util symbol.
import { trimAllStrict } from './util.js';

export function alphaGreet(name) {
  return 'hello ' + trimAllStrict(name);
}

export function alphaCount(items) {
  return items.length;
}
